-- ===========================================================================
--  ROW-LEVEL SECURITY
--
--  Layer 3 of the tenant isolation strategy. The application already
--  refuses to build an unscoped query; this makes the database refuse to
--  answer one. Both must fail before a gym can see another gym's data.
--
--  The runtime role is NOT superuser and NOT BYPASSRLS, so even raw SQL
--  issued by the application is filtered here.
--
--  GENERATED by scripts/generate-rls.mjs from the live schema.
--  Re-run it after adding a table; never hand-edit this file.
-- ===========================================================================

-- --------------------------------------------------------------- context --
-- Set per TRANSACTION with SET LOCAL, never per connection: a pooled
-- connection is reused by different tenants in sequence, and SET LOCAL is
-- the only form that is correct behind a transaction-mode pooler.
--
-- When the setting is absent, current_setting(..., true) returns NULL, the
-- comparison is NULL, and the policy denies. The failure mode is an empty
-- result set — never a leak.

CREATE OR REPLACE FUNCTION current_org_id() RETURNS uuid
  LANGUAGE sql STABLE
  SET search_path = pg_catalog
  AS $$ SELECT nullif(current_setting('app.current_org_id', true), '')::uuid $$;

CREATE OR REPLACE FUNCTION current_actor_id() RETURNS uuid
  LANGUAGE sql STABLE
  SET search_path = pg_catalog
  AS $$ SELECT nullif(current_setting('app.current_user_id', true), '')::uuid $$;

CREATE OR REPLACE FUNCTION is_platform_context() RETURNS boolean
  LANGUAGE sql STABLE
  SET search_path = pg_catalog
  AS $$ SELECT coalesce(current_setting('app.is_platform', true), 'off') = 'on' $$;

-- ----------------------------------------------------------------- grants --
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'gym_app') THEN
    RAISE NOTICE 'role gym_app does not exist; skipping grants';
    RETURN;
  END IF;
  EXECUTE 'GRANT USAGE ON SCHEMA public TO gym_app';
  EXECUTE 'GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO gym_app';
  EXECUTE 'GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO gym_app';
  EXECUTE 'ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO gym_app';
END $$;

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'gym_jobs') THEN
    RAISE NOTICE 'role gym_jobs does not exist; skipping grants';
    RETURN;
  END IF;
  EXECUTE 'GRANT USAGE ON SCHEMA public TO gym_jobs';
  EXECUTE 'GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO gym_jobs';
  EXECUTE 'ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO gym_jobs';
END $$;

-- attendance
ALTER TABLE "attendance" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "attendance" FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_isolation ON "attendance";
CREATE POLICY tenant_isolation ON "attendance"
  USING ("organizationId" = current_org_id())
  WITH CHECK ("organizationId" = current_org_id());

