-- org_users
-- a user must be able to see their own memberships to switch organization
ALTER TABLE "org_users" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "org_users" FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_isolation ON "org_users";
CREATE POLICY tenant_isolation ON "org_users"
  USING (is_platform_context()
        OR "organizationId" = current_org_id()
        OR "userId" = current_actor_id())
  WITH CHECK (is_platform_context() OR "organizationId" = current_org_id());

-- organizations
-- the tenant root: readable when it is the acting tenant, or when the actor is a member of it (the organization switcher)
ALTER TABLE "organizations" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "organizations" FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_isolation ON "organizations";
CREATE POLICY tenant_isolation ON "organizations"
  USING (is_platform_context()
        OR id = current_org_id()
        OR EXISTS (
             SELECT 1 FROM org_users ou
             WHERE ou."organizationId" = organizations.id
               AND ou."userId" = current_actor_id()
               AND ou."deletedAt" IS NULL
           ))
  WITH CHECK (is_platform_context() OR id = current_org_id());

